import MissionProgressBar from './components/MissionProgressBar.vue';
import IssueCard from '../Issues/components/IssueCard.vue';
import InboxDropdownItem from '../shared/InboxDropdownItem.vue';
import { renderMarkdown } from 'src/utils/markdown';
import { formatMissionSource } from 'src/utils/docnet/formatting';

export default defineComponent({
  name: 'DocNetMissionDetail',

  components: {
    StatusBadge,
    AssigneeChip,
    MissionProgressBar,
    IssueCard,
    InboxDropdownItem,
  },

  setup() {
    const missionStore = useDocNetMissionStore();
    const taskStore = useDocNetIssueStore();
    const agentStore = useDocNetAgentStore();
    const projectStore = useDocNetProjectStore();
    const wsStore = useDocNetWebSocketStore();
    const inboxStore = useDocNetInboxStore();
    const { currentMission: mission, loading } = storeToRefs(missionStore);
    const { issues: tasks, missionIssues } = storeToRefs(taskStore);
    const router = useRouter();
    const settingStore = useSettingStore();
    return { router, settingStore, missionStore, taskStore, agentStore, projectStore, wsStore, inboxStore, mission, loading, tasks, missionIssues };
  },

  data() {
    return {
      activeTab: 'issues' as string,
      showDeleteDialog: false,
      showEditDialog: false,
      showRestartDialog: false,
      restarting: false,
      editNameValue: '',
      messageText: '',
      stuckResumeText: '',
      wsUnsubscribe: null as (() => void) | null,
      pendingInboxItem: null as DocNetInboxItem | null,
      loadingInboxItem: false,
      // Mission-scoped tabs: fetched once from the server-side
      // aggregate endpoints.  Mission DTO doesn't embed these
      // (intentional — keeps the mission response small); the tabs
      // decide visibility from what's here.
      missionEmails: [] as DocNetMissionEmailSummary[],
      missionDocuments: [] as DocNetMissionDocumentRow[],
      loadingMissionEmails: false,
      loadingMissionDocuments: false,
    };
  },

  computed: {
    userLocale(): string {
      const amt = this.settingStore.user_settings?.AMOUNTS_LOCALE;
      return amt ? String(amt).replace('_', '-') : undefined;
    },

    progress(): number {
      if (!this.mission) return 0;
      // Total items = issues + mission itself
      const total = this.missionTasks.length + 1;
      const missionDone = this.mission.status === 'completed' ? 1 : 0;
      const issuesDone = this.missionTasks.filter((t) => t.status === 'done' || t.status === 'cancelled').length;
      return Math.round(((issuesDone + missionDone) / total) * 100);
    },

    hasPendingChildren(): boolean {
      return this.missionTasks.some(
        (t) =>
          t.assignee_type === 'agent' &&
          !['done', 'cancelled', 'error'].includes(t.status),
      );
    },

    /** Show queue mode only when agents are working and mission is NOT waiting for approval. */
    isQueued(): boolean {
      return this.hasPendingChildren && this.mission?.status !== 'waiting_approval';
    },

    missionTasks(): DocNetIssue[] {
      if (!this.mission) return [];
      // Use the mission-scoped issues list fetched by fetchMissionIssues —
      // this is independent of the paginated /doc-net/issues view so sub-issues
      // always reflect the full set regardless of the user's current page.
      return [...this.missionIssues]
        .sort((a, b) => new Date(a.created_on!).getTime() - new Date(b.created_on!).getTime());
    },

    /** Whether there's an in-flight agent task that a restart
     *  would race with.  Three signals, ANY of them counts:
     *    * Mission is in a live execution state (``running``,
     *      ``active``, ``waiting_approval``).
     *    * A non-terminal child issue exists (``in_progress``,
     *      ``in_review``).
     *    * A pending inbox approval is open.
     *  When any is set, the restart dialog shows a warning so
     *  the user knows they're cancelling work in flight — the
     *  cancellation guards on the backend prevent corruption,
     *  but the user should understand what they're doing
     *  before clicking. */
    hasActiveTask(): boolean {
      if (!this.mission) return false;
      const liveStatuses = ['running', 'active', 'waiting_approval'];
      if (liveStatuses.includes(this.mission.status as string)) return true;
      const nonTerminal = this.missionTasks.some(
        (t) => t.status === 'in_progress' || t.status === 'in_review',
      );
      if (nonTerminal) return true;
      return this.pendingInboxItem !== null;
    },

    missionWallClock(): number {
      if (!this.mission) return 0;
      const created = this.mission.created_on || this.mission.created_at;
      const modified = this.mission.last_modified_on || this.mission.updated_at;
      if (!created || !modified) return 0;
      const ms = new Date(modified).getTime() - new Date(created).getTime();
      return ms > 0 ? ms : 0;
    },

    contextUsage(): number {
      return this.mission?.result?.context_usage || 0;
    },

    contextWarning(): boolean {
      return !!this.mission?.result?.context_warning;
    },

    totalMissionTokens(): number {
      return this.mission?.token_usage?.billed ?? 0;
    },

    tokenBreakdown(): { orchestrator: number; agents: number } | null {
      const tu = this.mission?.token_usage;
      if (!tu?.orchestrator && !tu?.agents) return null;
      return {
        orchestrator: tu.orchestrator?.billed ?? 0,
        agents: tu.agents?.billed ?? 0,
      };
    },

    doneTasks(): number {
      return this.missionTasks.filter((t) => t.status === 'done').length;
    },

    statusBreakdown(): Array<{ status: string; count: number; hideLegend?: boolean }> {
      const counts: Record<string, number> = {};
      for (const t of this.missionTasks) {
        counts[t.status] = (counts[t.status] || 0) + 1;
      }
      const items: Array<{ status: string; count: number; hideLegend?: boolean }> =
        Object.entries(counts).map(([status, count]) => ({ status, count }));

      // Add mission itself to the bar but not the legend
      if (this.mission) {
        const missionStatus = this.mission.status === 'completed' ? 'done'
          : this.mission.status === 'active' ? 'in_progress'
          : this.mission.status;
        items.push({ status: missionStatus, count: 1, hideLegend: true });
      }
      return items;
    },

    missionProjects() {
      if (!this.mission) return [];
      const ids = this.mission.project_ids?.length ? this.mission.project_ids : (this.mission.project_id ? [this.mission.project_id] : []);
      return this.projectStore.projects.filter((p: { id: string }) => ids.includes(p.id));
    },

    /** Emails tab is offered only for email-sourced missions.  A
     * Mission Control / Discord / API mission never has an inbound
     * email to navigate to — rendering an empty tab there is noise. */
    showEmailsTab(): boolean {
      return (this.mission?.source ?? '') === 'email';
    },

    /** Documents tab is offered only when the server actually returned
     * at least one doc row.  We derive from ``missionDocuments`` (not
     * from the emails' ``document_ids`` list) so a doc2-api outage
     * that gives us zero enriched rows cleanly hides the tab instead
     * of showing an empty-but-implied one. */
    showDocumentsTab(): boolean {
      return this.missionDocuments.length > 0;
    },

    conversation(): DocNetMissionConversationEntry[] {
      return (this.mission?.result?.conversation ?? []).filter(
        (msg: any) => !msg.internal,
      );
    },

    isEmailMission(): boolean {
      return this.conversation.some((msg) => msg.source === 'email');
    },

    /** Human-readable source label shown as a badge (e.g. "Email").
     *  Goes through ``$t`` so the badge follows the active locale —
     *  English ``Email`` becomes ``E-Mail`` in German etc.  When the
     *  locale lacks a ``source_<token>`` key the helper falls back
     *  to the hardcoded English label. */
    namePrefix(): string {
      return formatMissionSource(
        this.mission,
        (k: string) => this.$t(k),
      );
    },

    /** Mission name as-is. Legacy "[Prefix]" was stripped from every
     * row in the DOCB-9880 data migration, so ``mission.name`` is
     * already the clean display name.
     */
    displayName(): string {
      return this.mission?.name ?? '';
    },

    waitingReason(): string {
      return this.mission?.result?.waiting_reason ?? '';
    },

    waitingAgent(): string {
      return this.mission?.result?.waiting_agent ?? '';
    },

  },

  watch: {
    'mission.status'(newStatus: string) {
      if (newStatus === 'waiting_approval') {
        this.fetchPendingInboxItem();
      } else {
        this.pendingInboxItem = null;
        this.loadingInboxItem = false;
      }
    },
    // doc2-api owns document state and doesn't push per-doc status
    // events to docnet, so the Documents tab can't subscribe to a
    // live feed.  Instead we refetch on the events we already have:
    // the user actively switching to the tab is a strong "show me
    // current" signal — cheap (1–5 rows) and matches the
    // "navigation aid, not live dashboard" framing of this tab.
    activeTab(newTab: string) {
      if (newTab === 'documents' && this.mission?.id) {
        this.refreshMissionDocumentsIfPresent(this.mission.id);
      }
    },
    // Single source of truth for "load this mission".  Fires on
    // initial mount (``immediate: true``) AND on every
    // ``$route.params.id`` change — Vue reuses this component
    // instance when only the param changes (same route definition,
    // different mission), so without this watcher
    // ``/missions/A → /missions/B`` would keep showing A's data
    // until an unrelated WS event happened to refetch.  Same
    // pattern ``DocNetMissionTimeline`` uses.
    '$route.params.id': {
      immediate: true,
      flush: 'sync',
      async handler(newId: string, oldId: string | undefined) {
        if (!newId) return;
        // Synchronously enter loading state and clear stale
        // data BEFORE awaiting any fetch.  Three flashes to
        // avoid here:
        //   1. ``currentMission`` from a previous route (Vue
        //      reuses the component on param change) leaking
        //      into the new mission's view.
        //   2. ``currentMission`` from the list cache being
        //      ``null`` for an unknown id, dropping into the
        //      "Mission not found" branch.
        //   3. ``loading`` flipping true only inside
        //      ``fetchMission`` (one microtask after we get
        //      here), giving the template one paint with
        //      ``currentMission=null`` and ``loading=false``
        //      — the same "not found" flash.
        // Setting both flags synchronously up front pins the
        // page on the spinner from the very first render after
        // navigation until the fetch resolves.
        this.missionStore.currentMission = null;
        this.missionStore.loading = true;
        if (oldId !== undefined && newId !== oldId && this.wsUnsubscribe) {
          this.wsUnsubscribe();
          this.wsUnsubscribe = null;
        }
        // Split into "blocks the spinner" and "background".
        //
        // Blocking fetches are mission-specific data the page
        // renders directly — without them the page would either
        // render incomplete (empty issues tab, empty conversation
        // panel) or fall back to the "Mission not found" branch.
        //
        // Background fetches are global lookups (agent profiles,
        // project lists) and the sidebar list.  None of them are
        // required for the detail page to render correctly — they
        // populate auxiliary UI that may or may not even be on
        // screen.  Gating the spinner on them was making the page
        // feel sluggish on slow networks: the user waits for the
        // sidebar list before seeing their selected mission.
        await Promise.all([
          this.missionStore.fetchMission(newId),
          this.taskStore.fetchMissionIssues(newId),
          this.fetchMissionEmails(newId),
          this.fetchMissionDocuments(newId),
          this.fetchPendingInboxItem(),
        ]);
        this.subscribeToMission(newId);

        // Fire-and-forget — these populate auxiliary state but
        // don't block the page render.  Errors are swallowed so
        // a flaky agent-profiles call doesn't surface as a page
        // load failure.  ``silent=true`` on ``fetchMissions``
        // keeps the list refresh from touching
        // ``missionStore.loading`` (we already cleared the
        // spinner with the awaited block above).
        this.missionStore.fetchMissions(true).catch(() => {});
        this.agentStore.fetchProfiles().catch(() => {});
        this.projectStore.fetchProjects().catch(() => {});
      },
    },
  },

  beforeUnmount() {
    if (this.wsUnsubscribe) {
      this.wsUnsubscribe();
      this.wsUnsubscribe = null;
    }
  },

  methods: {
    renderMarkdown,

    /** Subscribe to WS v2 events for the current mission */
    subscribeToMission(missionId: string) {
      if (this.wsUnsubscribe) {
        this.wsUnsubscribe();
      }
      this.wsUnsubscribe = this.wsStore.onMissionEvent(
        missionId,
        (eventType: string, data: MissionProgressEvent) => {
          this.handleMissionEvent(eventType, data);
        },
      );
    },

    handleMissionEvent(eventType: string, data: MissionProgressEvent) {
      const missionId = data.mission_id;
      if (!missionId) return;

      switch (eventType) {
        case DocNetGatewayEventType.AGENT_START:
          // Mission is now actively processing — update status to active
          this.missionStore.applyMissionEvent(missionId, { ...data, status: data.status || 'active' });
          break;

        case DocNetGatewayEventType.MISSION_AGGREGATE_CHANGED:
          // Backend signalled one of the mission-scoped lists changed.
          // ``kind`` narrows the refetch to exactly the aggregate that
          // moved — so a new document doesn't refetch the email list
          // and vice versa.  Unknown kinds are ignored.
          if (data.kind === 'document') {
            this.fetchMissionDocuments(missionId).catch(() => {});
          } else if (data.kind === 'email') {
            this.fetchMissionEmails(missionId).catch(() => {});
          }
          break;

        case DocNetGatewayEventType.MISSION_TIMELINE_APPENDED:
          // The unified timeline gained an event.  The mission detail
          // page itself doesn't render the timeline (full-page route
          // does), so nothing to do here — the timeline page handles
          // its own WS refresh.  Case kept so the catch-all doesn't
          // log an "unknown event" warning when this fires.
          break;

        case DocNetGatewayEventType.DELEGATION_STARTED:
          // A child issue was created — refresh the mission-scoped list
          // shown on this page.  The global /doc-net/issues list is
          // refreshed centrally by the WS store's
          // ``handleListChanged('issues')`` whenever the backend emits
          // ``LIST_CHANGED`` for the issue, so calling
          // ``fetchIssues(true)`` here would duplicate that work.
          this.taskStore.fetchMissionIssues(missionId).catch(() => {});
          break;

        case DocNetGatewayEventType.CHILD_COMPLETED:
          // Same reasoning as DELEGATION_STARTED — refresh the
          // mission-scoped list only; the global list is handled by
          // the WS store's centralised handler.
          this.taskStore.fetchMissionIssues(missionId).catch(() => {});
          break;

        case DocNetGatewayEventType.MISSION_PROGRESS:
          // Mission status update — apply and fetch latest
          this.missionStore.applyMissionEvent(missionId, data);
          // Agent-moved status is a strong proxy for "doc2-api may
          // have advanced this mission's documents too" — refresh
          // the badges if any docs are linked.  See
          // ``refreshMissionDocumentsIfPresent`` for why we don't
          // do this from a tool-level hook.
          this.refreshMissionDocumentsIfPresent(missionId);
          break;

        case DocNetGatewayEventType.MISSION_COMPLETED:
          // Mission finished — fetch full details + mission-scoped
          // issues list.  The global issues list refresh is handled
          // by the WS store's ``handleListChanged('issues')``.
          this.missionStore.fetchMission(missionId, true).catch(() => {});
          this.taskStore.fetchMissionIssues(missionId).catch(() => {});
          this.refreshMissionDocumentsIfPresent(missionId);
          break;

        case DocNetGatewayEventType.INBOX_ITEM_CREATED:
          // Approval request created — refresh mission (status may have changed
          // to waiting_approval) and the mission-scoped issues list.
          // Global list refresh is centralised in the WS store.
          this.missionStore.fetchMission(missionId, true).catch(() => {});
          this.taskStore.fetchMissionIssues(missionId).catch(() => {});
          this.fetchPendingInboxItem();
          break;

        case DocNetGatewayEventType.AGENT_COMPLETE:
          // v2: agent_complete is lightweight (mission_id, agent_name, status only)
          // Apply status from event, then fetch full mission details.
          this.missionStore.applyMissionEvent(missionId, data);
          this.missionStore.fetchMission(missionId, true).catch(() => {});
          // Refresh the mission-scoped issues list so sub-issue statuses
          // update.  The broader /doc-net/issues view is updated by the
          // WS store's centralised LIST_CHANGED handler.
          this.taskStore.fetchMissionIssues(missionId).catch(() => {});
          // Refresh inbox item if mission is now waiting for approval
          this.fetchPendingInboxItem();
          // Agent just stopped touching the doc — strongest moment
          // doc2-api status may have just advanced.
          this.refreshMissionDocumentsIfPresent(missionId);
          // Scroll conversation to bottom
          nextTick(() => {
            const el = this.$el?.querySelector?.('.conversation-msg:last-child');
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'end' });
          });
          break;
      }
    },

    getMemberName(memberId: string): string {
      const agentProfile = this.agentStore.getProfileById(memberId);
      if (agentProfile) {
        return agentProfile.agent.name;
      }
      return memberId;
    },

    getMemberType(memberId: string): 'human' | 'agent' {
      const agentProfile = this.agentStore.getProfileById(memberId);
      return agentProfile ? 'agent' : 'human';
    },

    formatDuration(ms: number): string {
      const secs = Math.round(ms / 1000);
      if (secs < 60) return `${secs}s`;
      const mins = Math.floor(secs / 60);
      if (mins < 60) return `${mins}m ${secs % 60}s`;
      const hours = Math.floor(mins / 60);
      return `${hours}h ${mins % 60}m`;
    },

    formatDate(isoString: string): string {
      const date = new Date(isoString);
      return date.toLocaleDateString(undefined, {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
      });
    },

    formatDateTime(isoString: string): string {
      if (!isoString) return '';
      const d = new Date(isoString);
      if (isNaN(d.getTime())) return '';
      return d.toLocaleString();
    },

    async onProjectChange(val: string[] | null): Promise<void> {
      if (!this.mission) return;
      const ids = val || [];
      await this.missionStore.updateMission(this.mission.id, {
        project_id: ids[0] || null,
        project_ids: ids,
      });
    },

    async onSendMessage(): Promise<void> {
      if (!this.mission || !this.messageText.trim()) return;
      const text = this.messageText.trim();
      this.messageText = '';
      try {
        await this.missionStore.sendMissionMessage(this.mission.id, text);
      } catch {
        // Error already logged in store; restore text so user can retry
        this.messageText = text;
      }
    },

    startEditName(): void {
      if (!this.mission) return;
      this.editNameValue = this.mission.name;
      this.showEditDialog = true;
    },

    /** Settings → Timeline navigates to a dedicated full-page route.
     *
     *  Uses ``router.replace`` (not ``push``) so the timeline does
     *  NOT add a history entry on top of the mission detail page.
     *  Conceptually the timeline is a sub-view of the mission, not
     *  a separate destination — without ``replace``, closing the
     *  mission detail via its back button would land back on the
     *  timeline (the previous history entry) instead of the page
     *  the user came from before opening the mission.
     *
     *  The timeline page has its own explicit back arrow
     *  (``:to="/doc-net/missions/<id>"``) for returning to detail,
     *  so we don't lose any navigation affordance. */
    goToTimeline(): void {
      if (!this.mission) return;
      void this.router.replace(`/doc-net/missions/${this.mission.id}/timeline`);
    },

    async saveEditName(): Promise<void> {
      if (!this.mission || !this.editNameValue.trim()) return;
      await this.missionStore.updateMission(this.mission.id, { name: this.editNameValue.trim() });
      this.showEditDialog = false;
    },

    async onRestart(): Promise<void> {
      if (!this.mission) return;
      this.restarting = true;
      try {
        await this.missionStore.restartMission(this.mission.id);
        this.showRestartDialog = false;
        notify.success(this.$t('docnet_mission_restarted'));
      } catch (err) {
        console.error('[DocNet] Restart failed:', err);
        notify.error(this.$t('docnet_restart_failed_retry'));
      } finally {
        this.restarting = false;
      }
    },

    async onDelete(): Promise<void> {
      if (!this.mission) return;
      await this.missionStore.deleteMission(this.mission.id);
      this.showDeleteDialog = false;
      this.goBack();
    },

    goBack() {
      if (window.history.length > 1) {
        this.router.back();
      } else {
        this.router.push('/doc-net/missions');
      }
    },

    async fetchPendingInboxItem(): Promise<void> {
      if (!this.mission || this.mission.status !== 'waiting_approval') {
        this.pendingInboxItem = null;
        return;
      }
      this.loadingInboxItem = true;
      try {
        await this.inboxStore.fetchItems();
        const item = this.inboxStore.items.find(
          (i) => i.mission_id === this.mission!.id && i.status === 'pending',
        );
        this.pendingInboxItem = item || null;
      } catch {
        this.pendingInboxItem = null;
      } finally {
        this.loadingInboxItem = false;
      }
    },

    /** Map a document status to its dashboard / extraction-tab color
     * class.  Kept in sync with ExtractedResultsTab.statusClass and
     * the dashboard's status-class mapping — if a new status is
     * introduced, update all three at once. */
    docStatusClass(status: string): string {
      const map: Record<string, string> = {
        new: 'bg-light-green-6',
        ready_for_review: 'bg-amber-7',
        ready_for_validation: 'bg-amber-7',
        validating: 'bg-amber-7',
        validated_pending_export: 'bg-amber-7',
        pending_confirmation: 'bg-amber-7',
        finished: 'bg-light-green-6',
        workflow: 'bg-light-green-6',
        completed: 'bg-light-green-6',
        restarted: 'bg-blue-14',
        running: 'bg-blue-14',
        in_progress: 'bg-blue-14',
        error: 'bg-red-13',
        export_error: 'bg-red-13',
        restart_export: 'bg-blue-14',
      };
      return map[status?.toLowerCase()] || 'bg-grey';
    },

    /** ``open_document`` is disabled while extraction is still in
     * flight — same set of "in flight" statuses the email tab uses.
     * Clicking into an unextracted doc throws the user into a
     * half-loaded validation screen.  Missing status is treated as
     * processing too: when doc2-api is transiently unavailable the row
     * has ``status: null`` and we'd rather keep the button disabled
     * than send the user into ``/field_validation_v1/<id>`` blind. */
    isDocProcessing(status: string | null | undefined): boolean {
      if (!status) return true;
      return ['new', 'running', 'restarted'].includes(status.toLowerCase());
    },

    async fetchMissionEmails(missionId: string): Promise<void> {
      // Single server-side aggregate call — no client-side filtering of
      // the global email list.  Errors are logged (not swallowed)
      // because an empty Emails tab is indistinguishable from a broken
      // fetch to the user; the browser console is the only diagnostic.
      this.loadingMissionEmails = true;
      try {
        const service = new DocNetMissionService();
        this.missionEmails = await service.getMissionEmails(missionId);
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn(`[mission ${missionId}] getMissionEmails failed:`, err);
        this.missionEmails = [];
      } finally {
        this.loadingMissionEmails = false;
      }
    },

    async fetchMissionDocuments(missionId: string): Promise<void> {
      // Server-side fan-out to doc2-api.  One HTTP call regardless of
      // how many emails / documents the mission collected.
      this.loadingMissionDocuments = true;
      try {
        const service = new DocNetMissionService();
        this.missionDocuments = await service.getMissionDocuments(missionId);
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn(`[mission ${missionId}] getMissionDocuments failed:`, err);
        this.missionDocuments = [];
      } finally {
        this.loadingMissionDocuments = false;
      }
    },

    // Background refetch used by agent-moved WS events
    // (AGENT_COMPLETE, MISSION_PROGRESS, MISSION_COMPLETED) and by
    // the activeTab watcher.  Skips the initial-load codepath when
    // no documents exist yet — the tab itself is hidden then, and
    // ``MISSION_AGGREGATE_CHANGED kind=document`` already covers
    // the "first document just appeared" transition.  Suppresses
    // the loading spinner so passing through "Loading documents…"
    // on every status flip doesn't flicker the tab.
    refreshMissionDocumentsIfPresent(missionId: string): void {
      if (this.missionDocuments.length === 0) return;
      const service = new DocNetMissionService();
      service.getMissionDocuments(missionId)
        .then((rows) => { this.missionDocuments = rows; })
        .catch(() => {});
    },

    async onInboxAct(evt: { id: string; action: string; payload?: { resolution_notes?: string } }): Promise<void> {
      if (!this.mission) return;
      try {
        // The backend act_on_item handles everything:
        // - Resolves the inbox item
        // - Resets mission to active (synchronous)
        // - Schedules orchestrator resume (async background)
        await this.inboxStore.actOnItem(evt.id, evt.action, evt.payload);
        this.pendingInboxItem = null;

        // Show loading spinner while the mission resumes — prevents
        // the fallback message input from flashing briefly.
        this.loadingInboxItem = true;
        notify.success(evt.action === 'comment'
          ? this.$t('docnet_message_sent_resuming')
          : this.$t('docnet_action_sent_resuming'),
        );

        // Refresh mission — for approve/reject status should already be active.
        // For comment, it will change once the async resume completes.
        // Also refresh the mission-scoped issues list so card statuses
        // reflect the new backend state (inboxStore.actOnItem already
        // refreshes the individual acted-upon issue, but sub-issues that
        // cascaded on resume need the list refetch to update).
        if (this.mission) {
          await this.missionStore.fetchMission(this.mission.id, true);
          this.taskStore.fetchMissionIssues(this.mission.id).catch(() => {});
        }
      } catch (err) {
        console.error('[DocNet] Approval action failed:', err);
        notify.error(this.$t('docnet_action_failed_retry'));
        if (this.mission) {
          await this.missionStore.fetchMission(this.mission.id, true);
          await this.fetchPendingInboxItem();
        }
      }
    },

    async resumeStuckMission(): Promise<void> {
      if (!this.mission || !this.stuckResumeText.trim()) return;
      const text = this.stuckResumeText.trim();
      this.stuckResumeText = '';
      try {
        await this.missionStore.sendMissionMessage(this.mission.id, text);
      } catch (err) {
        console.error('[DocNet] Resume stuck mission failed:', err);
        this.stuckResumeText = text;
        notify.error(this.$t('docnet_send_failed_retry'));
      }
    },

    async onInboxDismiss(id: string): Promise<void> {
      try {
        await this.inboxStore.dismissItem(id);
        this.pendingInboxItem = null;
      } catch {
        notify.error(this.$t('docnet_dismiss_failed_retry'));
      }
    },

  },
});
</script>

