<template>
  <div
    class="issue-card"
    :class="['issue-card--priority-' + task.priority]"
    @click="$emit('click', task)"
  >
    <!-- Top row: status dot + type badge, spanning the full card width
         so the badge stays pinned to the top-right corner even when an
         action button is shown below on the right. -->
    <div class="issue-card__top">
      <span class="issue-card__status-dot" :class="'issue-card__status-dot--' + task.status" />
      <q-space />
      <q-badge
        :label="task.type"
        color="blue-grey-3"
        text-color="blue-grey-9"
        class="issue-card__type"
      />
    </div>

    <!-- Main row: content on the left, optional action centred on the
         right.  With no action slot (kanban board) the content fills
         the row and the layout is unchanged. -->
    <div class="issue-card__main">
      <div class="issue-card__content">
        <!-- Title (2-line wrap) -->
        <div class="issue-card__title">{{ task.title }}</div>

        <!-- Tags -->
        <div v-if="task.tags && task.tags.length" class="issue-card__tags">
          <q-chip
            v-for="tag in task.tags"
            :key="tag"
            dense
            size="xs"
            color="blue-grey-1"
            text-color="blue-grey-8"
            class="issue-card__tag"
          >
            {{ tag }}
          </q-chip>
        </div>

        <!-- Bottom row: Assignee left, Due date right -->
        <div class="issue-card__bottom">
          <div class="row items-center no-wrap q-gutter-xs">
            <AssigneeChip
              :name="task.assignee_name"
              :type="task.assignee_type === 'agent' ? 'agent' : 'human'"
              size="sm"
            />
            <q-badge
              v-if="assigneeStatus"
              :color="assigneeStatus.color"
              :label="assigneeStatus.label"
              class="issue-card__agent-status"
            />
          </div>
          <span v-if="task.due_date" class="issue-card__due" :class="{ 'issue-card__due--overdue': isOverdue }">
            <q-icon name="event" size="14px" />
            {{ formattedDueDate }}
          </span>
        </div>
      </div>

      <!-- Optional action (e.g. an Open button) injected by the parent,
           vertically centred on the right. -->
      <div v-if="$slots.footer" class="issue-card__action">
        <slot name="footer" />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetIssue } from 'src/@types/docnet';
import AssigneeChip from '../../shared/AssigneeChip.vue';
import { statusLabel } from '../../shared/docnet-labels';

export default defineComponent({
  name: 'IssueCard',
  components: {
    AssigneeChip,
  },
  props: {
    task: {
      type: Object as PropType<DocNetIssue>,
      required: true,
    },
  },
  emits: ['click'],
  computed: {
    formattedDueDate(): string {
      if (!this.task.due_date) return '';
      const date = new Date(this.task.due_date);
      return date.toLocaleDateString(undefined, {
        month: 'short',
        day: 'numeric',
      });
    },

    isOverdue(): boolean {
      if (!this.task.due_date) return false;
      return new Date(this.task.due_date) < new Date() && this.task.status !== 'done';
    },

    assigneeStatus(): { label: string; color: string } | null {
      if (!this.task.assignee_type) return null;
      // Status → ``(translation key, color)``.  The label is
      // resolved via ``$t('status_<name>')`` so the badge picks
      // up the same translations as ``<StatusBadge>``.  Unknown
      // statuses return null — better to render no badge than
      // a misleading default — so the caller can decide how to
      // handle that case (typically: don't show the badge).
      const STATUS: Record<string, { color: string }> = {
        done: { color: 'positive' },
        cancelled: { color: 'grey' },
        error: { color: 'negative' },
        in_progress: { color: 'blue' },
        in_review: { color: 'orange' },
        todo: { color: 'grey-7' },
      };
      const entry = STATUS[this.task.status as string];
      if (!entry) return null;
      return { label: statusLabel(this.$t, this.task.status as string), color: entry.color };
    },
  },
});
</script>

